/**
 * @name Command injection in git utils
 * @description Traces flow from function parameters to subprocess calls in git utils
 * @kind path-problem
 * @problem.severity error
 * @id py/git-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module GitCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["check_output", "run", "call", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module GitCommandInjectionFlow = TaintTracking::Global<GitCommandInjectionConfig>;
import GitCommandInjectionFlow::PathGraph

from GitCommandInjectionFlow::PathNode source, GitCommandInjectionFlow::PathNode sink
where GitCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "parameter"
